index 9fa8c53..9962bca 100644
--- a/src/cache.ts
+++ b/src/cache.ts
@@ -1,19 +1,66 @@
+import { readFileSync, writeFileSync, existsSync } from "fs";
+import { join } from "path";
+
 interface Entry {
   value: string;
   expiresAt: number;
 }

-const store = new Map<string, Entry>();
+const STORE_FILE = join(process.cwd(), ".session-store.json");
+const memory = new Map<string, Entry>();
+let lastSyncTime = 0;
+const SYNC_INTERVAL_MS = 5000;
+
+const loadFromDisk = (): Map<string, Entry> => {
+  if (!existsSync(STORE_FILE)) {
+    return new Map();
+  }
+  try {
+    const data = readFileSync(STORE_FILE, "utf-8");
+    const entries = JSON.parse(data);
+    return new Map(entries);
+  } catch {
+    return new Map();
+  }
+};
+
+const saveToDisk = (): void => {
+  try {
+    const entries = Array.from(memory.entries());
+    writeFileSync(STORE_FILE, JSON.stringify(entries));
+  } catch {
+    // Silent failure on disk write
+  }
+};
+
+const syncMemory = (): void => {
+  const now = Date.now();
+  if (now - lastSyncTime >= SYNC_INTERVAL_MS) {
+    saveToDisk();
+    lastSyncTime = now;
+  }
+};

 export const put = (key: string, value: string, ttlMs: number): void => {
-  store.set(key, { value, expiresAt: Date.now() + ttlMs });
+  memory.set(key, { value, expiresAt: Date.now() + ttlMs });
+  syncMemory();
 };

 export const get = (key: string): string | null => {
-  const entry = store.get(key);
+  let entry = memory.get(key);
+
+  if (entry === undefined) {
+    const diskData = loadFromDisk();
+    entry = diskData.get(key);
+    if (entry !== undefined) {
+      memory.set(key, entry);
+    }
+  }
+
   if (entry === undefined) return null;
   if (entry.expiresAt < Date.now()) {
-    store.delete(key);
+    memory.delete(key);
+    syncMemory();
     return null;
   }
   return entry.value;
